// ==================== CÁC COMPONENT NÂNG CẤP BẢO TÀNG ====================
function createAoDaiGuide() {
  const guideGroup = new It();
  const skinMat = new X({ color: "#fcd34d", roughness: 0.45, metalness: 0.05 });
  const aoDaiRedMat = new X({ color: "#991b1b", roughness: 0.35, metalness: 0.25 });
  const goldTrimMat = new X({ color: "#fbbf24", roughness: 0.2, metalness: 0.85 });
  const whiteSilkMat = new X({ color: "#f8fafc", roughness: 0.3 });
  const hairMat = new X({ color: "#18181b", roughness: 0.5 });
  const lipMat = new X({ color: "#e11d48", roughness: 0.3 });

  // Shoes
  const shoeGeo = new Z(0.12, 0.05, 0.2);
  const shoeLeft = new I(shoeGeo, hairMat);
  shoeLeft.position.set(-0.1, 0.025, 0);
  const shoeRight = new I(shoeGeo, hairMat);
  shoeRight.position.set(0.1, 0.025, 0);
  guideGroup.add(shoeLeft);
  guideGroup.add(shoeRight);

  // White silk pants
  const legGeo = new Rt(0.065, 0.08, 0.72, 12);
  const legLeft = new I(legGeo, whiteSilkMat);
  legLeft.position.set(-0.1, 0.4, 0);
  const legRight = new I(legGeo, whiteSilkMat);
  legRight.position.set(0.1, 0.4, 0);
  guideGroup.add(legLeft);
  guideGroup.add(legRight);

  // Áo dài flaps
  const flapGeo = new Yt(0.28, 0.65);
  const flapFront = new I(flapGeo, aoDaiRedMat);
  flapFront.position.set(0, 0.45, 0.09);
  const flapBack = new I(flapGeo, aoDaiRedMat);
  flapBack.position.set(0, 0.45, -0.09);
  flapBack.rotation.y = Math.PI;
  guideGroup.add(flapFront);
  guideGroup.add(flapBack);

  // Torso
  const torsoGeo = new Rt(0.11, 0.14, 0.45, 16);
  const torsoMesh = new I(torsoGeo, aoDaiRedMat);
  torsoMesh.position.set(0, 0.95, 0);
  guideGroup.add(torsoMesh);

  // Gold sash belt
  const sashGeo = new Z(0.24, 0.04, 0.2);
  const sashMesh = new I(sashGeo, goldTrimMat);
  sashMesh.position.set(0, 0.85, 0);
  guideGroup.add(sashMesh);

  // Collar
  const collarGeo = new Rt(0.06, 0.06, 0.06, 16);
  const collarMesh = new I(collarGeo, goldTrimMat);
  collarMesh.position.set(0, 1.2, 0);
  guideGroup.add(collarMesh);

  // Neck
  const neckGeo = new Rt(0.05, 0.05, 0.08, 16);
  const neckMesh = new I(neckGeo, skinMat);
  neckMesh.position.set(0, 1.22, 0);
  guideGroup.add(neckMesh);

  // Head
  const headGeo = new sr(0.11, 16, 16);
  const headMesh = new I(headGeo, skinMat);
  headMesh.scale.set(1, 1.15, 1);
  headMesh.position.set(0, 1.35, 0);
  guideGroup.add(headMesh);

  // Eyes
  const eyeGeo = new sr(0.015, 8, 8);
  const eyeMat = new X({ color: "#0f172a", roughness: 0.1 });
  const eyeLeft = new I(eyeGeo, eyeMat);
  eyeLeft.position.set(-0.04, 1.36, 0.1);
  const eyeRight = new I(eyeGeo, eyeMat);
  eyeRight.position.set(0.04, 1.36, 0.1);
  guideGroup.add(eyeLeft);
  guideGroup.add(eyeRight);

  // Mouth for dynamic lip-sync
  const mouthGeo = new Z(0.04, 0.012, 0.01);
  const mouthMesh = new I(mouthGeo, lipMat);
  mouthMesh.position.set(0, 1.3, 0.108);
  guideGroup.add(mouthMesh);

  // Hair
  const hairGeo = new sr(0.12, 16, 16);
  const hairMesh = new I(hairGeo, hairMat);
  hairMesh.scale.set(1.04, 1.1, 1.05);
  hairMesh.position.set(0, 1.38, -0.02);
  guideGroup.add(hairMesh);

  const hairBackGeo = new Rt(0.08, 0.03, 0.5, 12);
  const hairBack = new I(hairBackGeo, hairMat);
  hairBack.position.set(0, 1.05, -0.12);
  guideGroup.add(hairBack);

  // Arms
  const armGeo = new Rt(0.035, 0.03, 0.35, 8);
  const armLeft = new I(armGeo, aoDaiRedMat);
  armLeft.position.set(-0.16, 0.95, 0.05);
  armLeft.rotation.z = -0.25;
  armLeft.rotation.x = 0.35;
  const armRight = new I(armGeo, aoDaiRedMat);
  armRight.position.set(0.16, 0.95, 0.05);
  armRight.rotation.z = 0.25;
  armRight.rotation.x = 0.35;
  guideGroup.add(armLeft);
  guideGroup.add(armRight);

  // Hands
  const handGeo = new sr(0.035, 8, 8);
  const handLeft = new I(handGeo, skinMat);
  handLeft.position.set(-0.04, 0.8, 0.14);
  const handRight = new I(handGeo, skinMat);
  handRight.position.set(0.04, 0.8, 0.14);
  guideGroup.add(handLeft);
  guideGroup.add(handRight);

  // Hit box
  const hitBox = new I(new Z(0.6, 1.7, 0.5), new Se({ visible: false }));
  hitBox.position.set(0, 0.85, 0);
  guideGroup.add(hitBox);

  return { group: guideGroup, mouthMesh, hitBox };
}

const QuizGameModal = ({ room, quizData, onClose }) => {
  const [currentIdx, setCurrentIdx] = nt.useState(0);
  const [selectedKey, setSelectedKey] = nt.useState(null);
  const [isAnswered, setIsAnswered] = nt.useState(false);
  const [score, setScore] = nt.useState(0);
  const [isFinished, setIsFinished] = nt.useState(false);

  const questions = quizData?.questions || [];
  const q = questions[currentIdx] || null;
  const total = questions.length || 5;

  const handleSelect = (key) => {
    if (isAnswered) return;
    setSelectedKey(key);
    setIsAnswered(true);
    const isCorrect = key === q.correctAnswer;
    if (isCorrect) {
      setScore(s => s + 1);
      ln.speak("Chính xác! " + (q.explanation || ""));
    } else {
      ln.speak("Chưa chính xác. Đáp án đúng là " + q.correctAnswer + ". " + (q.explanation || ""));
    }
  };

  const handleNext = () => {
    if (currentIdx < total - 1) {
      setCurrentIdx(i => i + 1);
      setSelectedKey(null);
      setIsAnswered(false);
    } else {
      setIsFinished(true);
      const finalScore = score + (selectedKey === q.correctAnswer ? 1 : 0);
      ln.speak("Bạn đã hoàn thành bài luyện tập với số điểm " + finalScore + " trên " + total + "!");
    }
  };

  const handleRestart = () => {
    setCurrentIdx(0);
    setSelectedKey(null);
    setIsAnswered(false);
    setScore(0);
    setIsFinished(false);
  };

  const gameEmoji = room?.id === "lesson-2" ? "🌱🧟" : room?.id === "lesson-3" ? "🧗🏔️" : "🚣‍♂️🌊";

  return p.jsx("div", {
    style: {
      position: "fixed", inset: 0, zIndex: 9999,
      backgroundColor: "rgba(10, 12, 16, 0.88)",
      backdropFilter: "blur(12px)",
      display: "flex", alignItems: "center", justifyContent: "center",
      padding: "20px", fontFamily: "'Be Vietnam Pro', sans-serif"
    },
    children: p.jsxs("div", {
      style: {
        background: "linear-gradient(135deg, #131722 0%, #1a202c 100%)",
        border: "2px solid #d4af37",
        borderRadius: "24px",
        boxShadow: "0 25px 60px rgba(0,0,0,0.85), 0 0 35px rgba(212,175,55,0.3)",
        maxWidth: "680px", width: "100%", padding: "28px 32px",
        color: "#f8fafc", position: "relative"
      },
      children: [
        p.jsxs("div", {
          style: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" },
          children: [
            p.jsxs("div", {
              children: [
                p.jsxs("div", {
                  style: { color: "#fbbf24", fontSize: "12px", fontWeight: 800, textTransform: "uppercase", letterSpacing: "1px" },
                  children: [gameEmoji, " ", quizData?.gameName || "TRẮC NGHIỆM LỊCH SỬ"]
                }),
                p.jsx("h2", {
                  style: { fontSize: "20px", fontWeight: 800, color: "#ffffff", margin: "4px 0 0 0", fontFamily: "serif" },
                  children: quizData?.lessonTitle || room?.name
                })
              ]
            }),
            p.jsx("button", {
              onClick: onClose,
              style: {
                background: "rgba(255,255,255,0.08)", border: "1px solid rgba(255,255,255,0.15)",
                color: "#94a3b8", borderRadius: "50%", width: "36px", height: "36px",
                fontSize: "16px", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center"
              },
              children: "✕"
            })
          ]
        }),

        !isFinished && q && p.jsxs("div", {
          children: [
            p.jsxs("div", {
              style: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "8px", fontSize: "13px", color: "#fde68a" },
              children: [
                p.jsxs("span", { children: ["Câu ", currentIdx + 1, " / ", total] }),
                p.jsxs("span", { children: ["Điểm: ", score, " / ", total] })
              ]
            }),
            p.jsx("div", {
              style: { width: "100%", height: "6px", backgroundColor: "rgba(255,255,255,0.1)", borderRadius: "3px", marginBottom: "20px", overflow: "hidden" },
              children: p.jsx("div", {
                style: { width: ((currentIdx + 1) / total * 100) + "%", height: "100%", background: "linear-gradient(90deg, #d4af37, #10b981)", transition: "width 0.3s ease" }
              })
            }),
            p.jsx("p", {
              style: { fontSize: "16px", fontWeight: 600, lineHeight: "1.6", color: "#ffffff", marginBottom: "20px" },
              children: q.question
            }),
            p.jsx("div", {
              style: { display: "flex", flexDirection: "column", gap: "10px", marginBottom: "20px" },
              children: q.options.map(opt => {
                const isSelected = selectedKey === opt.key;
                const isCorrect = opt.key === q.correctAnswer;
                let bg = "rgba(30, 41, 59, 0.6)";
                let borderColor = "rgba(212, 175, 55, 0.25)";
                let textColor = "#f1f5f9";
                if (isAnswered) {
                  if (isCorrect) {
                    bg = "rgba(16, 185, 129, 0.25)";
                    borderColor = "#10b981";
                    textColor = "#34d399";
                  } else if (isSelected) {
                    bg = "rgba(239, 68, 68, 0.25)";
                    borderColor = "#ef4444";
                    textColor = "#f87171";
                  }
                }
                return p.jsxs("button", {
                  key: opt.key,
                  onClick: () => handleSelect(opt.key),
                  disabled: isAnswered,
                  style: {
                    display: "flex", alignItems: "center", gap: "12px",
                    padding: "12px 18px", borderRadius: "14px",
                    backgroundColor: bg, border: "1.5px solid " + borderColor,
                    color: textColor, textAlign: "left", fontSize: "14px",
                    cursor: isAnswered ? "default" : "pointer",
                    transition: "all 0.2s ease"
                  },
                  children: [
                    p.jsx("span", {
                      style: {
                        width: "28px", height: "28px", borderRadius: "50%",
                        backgroundColor: isSelected ? (isCorrect ? "#10b981" : "#ef4444") : "rgba(212, 175, 55, 0.15)",
                        color: isSelected ? "#ffffff" : "#fbbf24",
                        display: "flex", alignItems: "center", justifyContent: "center",
                        fontWeight: 800, fontSize: "13px", flexShrink: 0
                      },
                      children: opt.key
                    }),
                    p.jsx("span", { style: { flex: 1, lineHeight: "1.4" }, children: opt.text })
                  ]
                });
              })
            }),

            isAnswered && p.jsxs("div", {
              style: {
                background: selectedKey === q.correctAnswer ? "rgba(16, 185, 129, 0.15)" : "rgba(239, 68, 68, 0.15)",
                border: "1px solid " + (selectedKey === q.correctAnswer ? "#10b981" : "#ef4444"),
                borderRadius: "14px", padding: "14px 18px", marginBottom: "20px"
              },
              children: [
                p.jsx("div", {
                  style: { fontWeight: 800, fontSize: "13px", color: selectedKey === q.correctAnswer ? "#34d399" : "#f87171", marginBottom: "4px" },
                  children: selectedKey === q.correctAnswer ? "✓ CHÍNH XÁC!" : ("✕ CHƯA ĐÚNG! (Đáp án: " + q.correctAnswer + ")")
                }),
                p.jsx("div", { style: { fontSize: "13px", color: "#cbd5e1", lineHeight: "1.5" }, children: q.explanation })
              ]
            }),

            isAnswered && p.jsx("div", {
              style: { display: "flex", justifyContent: "flex-end" },
              children: p.jsxs("button", {
                onClick: handleNext,
                style: {
                  background: "linear-gradient(135deg, #d4af37 0%, #b45309 100%)",
                  color: "#000000", border: "none", borderRadius: "24px",
                  padding: "10px 24px", fontWeight: 800, fontSize: "14px",
                  cursor: "pointer", display: "flex", alignItems: "center", gap: "8px",
                  boxShadow: "0 4px 15px rgba(212, 175, 55, 0.4)"
                },
                children: [
                  p.jsx("span", { children: currentIdx < total - 1 ? "Câu Tiếp Theo" : "Xem Kết Quả" }),
                  p.jsx("span", { children: "▶" })
                ]
              })
            })
          ]
        }),

        isFinished && p.jsxs("div", {
          style: { textAlign: "center", padding: "20px 0" },
          children: [
            p.jsx("div", { style: { fontSize: "48px", marginBottom: "12px" }, children: score >= 4 ? "🏆" : "🎖️" }),
            p.jsx("h3", { style: { fontSize: "22px", fontWeight: 800, color: "#fbbf24", margin: "0 0 10px 0" }, children: score >= 4 ? "XUẤT SẮC!" : "HOÀN THÀNH BÀI TẬP" }),
            p.jsxs("p", {
              style: { fontSize: "16px", color: "#e2e8f0", margin: "0 0 24px 0" },
              children: ["Bạn đã trả lời đúng ", p.jsx("strong", { style: { color: "#34d399", fontSize: "20px" }, children: score }), " / ", total, " câu hỏi!"]
            }),
            p.jsxs("div", {
              style: { display: "flex", gap: "12px", justifyContent: "center" },
              children: [
                p.jsx("button", {
                  onClick: handleRestart,
                  style: {
                    background: "rgba(255,255,255,0.1)", border: "1px solid #d4af37",
                    color: "#fde68a", borderRadius: "24px", padding: "10px 22px",
                    fontWeight: 700, fontSize: "13px", cursor: "pointer"
                  },
                  children: "🔄 Làm lại bài tập"
                }),
                p.jsx("button", {
                  onClick: onClose,
                  style: {
                    background: "linear-gradient(135deg, #d4af37 0%, #b45309 100%)",
                    color: "#000", border: "none", borderRadius: "24px",
                    padding: "10px 24px", fontWeight: 800, fontSize: "13px", cursor: "pointer"
                  },
                  children: "Đóng & Tiếp tục tham quan"
                })
              ]
            })
          ]
        })
      ]
    })
  });
};

const DioramaMiniSelector = ({ room, onSelectMarker }) => {
  const config = (typeof yp !== 'undefined' && (yp[room?.id] || yp["lesson-1"])) || null;
  const markers = config?.eventMarkers || [];
  if (!markers || markers.length === 0) return null;
  return p.jsxs("div", {
    style: {
      position: "fixed", top: "120px", left: "20px", zIndex: 40,
      background: "rgba(15, 23, 42, 0.92)", backdropFilter: "blur(12px)",
      border: "1.5px solid #d4af37", borderRadius: "18px", padding: "12px 16px",
      boxShadow: "0 10px 30px rgba(0,0,0,0.6)", maxWidth: "260px",
      fontFamily: "'Be Vietnam Pro', sans-serif"
    },
    children: [
      p.jsx("div", {
        style: { fontSize: "12px", fontWeight: 800, color: "#fbbf24", marginBottom: "8px", textTransform: "uppercase" },
        children: "🔭 MỐC SỰ KIỆN SA BÀN"
      }),
      p.jsx("div", {
        style: { display: "flex", flexDirection: "column", gap: "6px" },
        children: markers.map((m, idx) => p.jsxs("button", {
          key: m.id || idx,
          onClick: () => onSelectMarker(m),
          style: {
            background: "rgba(30, 41, 59, 0.6)", border: "1px solid rgba(212, 175, 55, 0.3)",
            color: "#f1f5f9", borderRadius: "10px", padding: "7px 10px",
            fontSize: "11px", fontWeight: 600, textAlign: "left", cursor: "pointer",
            display: "flex", alignItems: "center", gap: "6px"
          },
          children: [
            p.jsx("span", { children: m.iconText || "★" }),
            p.jsx("span", { style: { flex: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }, children: m.title })
          ]
        }))
      })
    ]
  });
};

