// HÀM TẠO TRANH KHỔ LỚN SANG TRỌNG (ẢNH 1: KHUNG GỖ NÂU, VIỀN VÀNG, BẢNG ĐỒNG, SPOTLIGHT)
// =========================================================================
// HÀM TẠO GIÁ ĐỠ TRANH BẢO TÀNG CHÂN GỖ MẠ ĐỒNG (SA BÀN GALLERY EASEL STAND)
function createEaselGalleryStand({
  x = 0, y = 0, z = 0, rotY = 0, width = 1.6, height = 1.1,
  title = "", year = "", imageUrl = "", description = "", onRegisterInteractive = null
}) {
  const g = new It();
  g.position.set(x, y, z);
  g.rotation.y = rotY;

  const woodMat = new X({ color: "#2d1d13", roughness: 0.45, metalness: 0.12 });
  const goldMat = new X({ color: "#d4af37", roughness: 0.20, metalness: 0.90 });

  // 3 chân giá chữ A vững chãi
  const legGeom = new Z(0.06, 1.9, 0.06);
  const legL = new I(legGeom, woodMat);
  legL.position.set(-0.55, 0.95, 0.12);
  legL.rotation.z = -0.16; legL.rotation.x = -0.14;
  g.add(legL);

  const legR = new I(legGeom, woodMat);
  legR.position.set(0.55, 0.95, 0.12);
  legR.rotation.z = 0.16; legR.rotation.x = -0.14;
  g.add(legR);

  const legBack = new I(new Z(0.06, 1.85, 0.06), woodMat);
  legBack.position.set(0, 0.92, -0.42);
  legBack.rotation.x = 0.28;
  g.add(legBack);

  // Thanh ngang đỡ tranh viền đồng
  const shelf = new I(new Z(width + 0.25, 0.08, 0.16), woodMat);
  shelf.position.set(0, 0.92, 0.14);
  g.add(shelf);

  const shelfGold = new I(new Z(width + 0.27, 0.02, 0.17), goldMat);
  shelfGold.position.set(0, 0.88, 0.14);
  g.add(shelfGold);

  // Khung tranh nghiêng tựa vào giá (~12 độ)
  const frameGroup = new It();
  frameGroup.position.set(0, 0.96 + height / 2, 0.14);
  frameGroup.rotation.x = -0.15;

  const outer = new I(new Z(width + 0.16, height + 0.16, 0.06), woodMat);
  frameGroup.add(outer);
  const innerGold = new I(new Z(width + 0.04, height + 0.04, 0.07), goldMat);
  frameGroup.add(innerGold);

  const canvas = document.createElement("canvas");
  canvas.width = 1024; canvas.height = 700;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.fillStyle = "#0c1726"; ctx.fillRect(0, 0, 1024, 700);
    ctx.fillStyle = "#38bdf8"; ctx.font = 'bold 30px sans-serif'; ctx.textAlign = "center";
    ctx.fillText(title || "Sa Bàn 3D", 512, 350);
  }
  const tex = new Pe(canvas);
  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;
  img.onload = () => {
    if (ctx) {
      try {
        const nw = img.naturalWidth || 1024, nh = img.naturalHeight || 700;
        const r = Math.max(1024 / nw, 700 / nh);
        ctx.drawImage(img, 0, 0, nw, nh, (1024 - nw * r) / 2, (700 - nh * r) / 2, nw * r, nh * r);
      } catch (e) { ctx.drawImage(img, 0, 0, 1024, 700); }
      tex.needsUpdate = true;
    }
  };
  if (img.complete && (img.naturalWidth > 0 || img.width > 0)) img.onload();

  const artMesh = new I(new Yt(width, height), new Se({ map: tex, side: Xe }));
  artMesh.position.z = 0.04;
  frameGroup.add(artMesh);

  // Bảng đồng khắc tên sa bàn
  const pCv = document.createElement("canvas");
  pCv.width = 512; pCv.height = 120;
  const pctx = pCv.getContext("2d");
  if (pctx) {
    pctx.fillStyle = "#1e130a"; pctx.fillRect(0, 0, 512, 120);
    pctx.strokeStyle = "#d4af37"; pctx.lineWidth = 4; pctx.strokeRect(6, 6, 500, 108);
    pctx.fillStyle = "#fef08a"; pctx.font = 'bold 22px "Cinzel", Georgia, serif'; pctx.textAlign = "center";
    pctx.fillText("⭐ SA BÀN TRIỂN LÃM 3D", 256, 38);
    pctx.fillStyle = "#ffffff"; pctx.font = 'bold 18px "Be Vietnam Pro", sans-serif';
    pctx.fillText(title.length > 30 ? title.slice(0, 28) + "..." : title, 256, 80);
  }
  const pMesh = new I(new Yt(0.85, 0.22), new Se({ map: new Pe(pCv), side: Xe }));
  pMesh.position.set(0, -height / 2 - 0.16, 0.05);
  frameGroup.add(pMesh);

  g.add(frameGroup);

  const spot = new sa("#fffbeb", 1.8, 5.0, Math.PI / 4, 0.5);
  spot.position.set(0, 2.1, 0.8);
  spot.target = artMesh;
  g.add(spot);
  g.add(spot.target);

  if (onRegisterInteractive) {
    onRegisterInteractive(artMesh, "🕹️ " + title + " (" + year + ")", {
      title, year, imageUrl, description, shortDescription: description
    });
    onRegisterInteractive(pMesh, "🕹️ " + title + " (" + year + ")", {
      title, year, imageUrl, description, shortDescription: description
    });
  }

  return { group: g, artMesh, plaqueMesh: pMesh };
}

function createGrandArtFrame({
  x = 0, y = 2.4, z = 0, width = 3.2, height = 2.0, rotY = 0,
  title = "", year = "", imageUrl = "", description = "", onRegisterInteractive = null,
  scaleMultiplier = 1.0, scale = 1.0
}) {
  if (x < -9.2) {
    scaleMultiplier = 1.4;
    scale = 1.4;
  }
  width = width * scaleMultiplier;
  height = height * scaleMultiplier;
  const g = new It();
  g.position.set(x, y, z);
  g.rotation.y = rotY;

  // =========================================================================
  // HỆ THỐNG KHUNG TRANH BẢO TÀNG 5 LỚP CAO CẤP (MUSEUM GRADE 5-LAYER 3D FRAME)
  // Lớp 1: Khung phào chỉ gỗ óc chó cổ điển (Dark Walnut Wood Molding)
  // Lớp 2: Chỉ viền nẹp vàng hoàng gia nổi vát (Beveled Champagne Gold Fillet)
  // Lớp 3: Bo viền đệm gấm lụa bảo tàng (Cream Linen Passe-Partout Mat)
  // Lớp 4: Nẹp viền chỉ góc trong mạ vàng lá (Beveled Inner Gold Trim)
  // Lớp 5: Tấm tranh nghệ thuật PBR chống méo hình (Canvas Art Plate)
  // =========================================================================

  // LỚP 1: Khung ngoài gỗ óc chó nâu đậm
  const outerMat = new X({ color: "#22150c", roughness: 0.52, metalness: 0.18 });
  const outerMesh = new I(new Z(width + 0.36, height + 0.36, 0.08), outerMat);
  outerMesh.castShadow = true;
  g.add(outerMesh);

  // LỚP 2: Nẹp viền vàng champagne hoàng gia nổi vát (nhô ra phía trước +0.015m)
  const goldFilletMat = new X({ color: "#d4af37", roughness: 0.22, metalness: 0.90 });
  const goldFilletMesh = new I(new Z(width + 0.22, height + 0.22, 0.095), goldFilletMat);
  g.add(goldFilletMesh);

  // LỚP 3: Lớp đệm bo gấm/lụa màu be kem (Passe-partout mat)
  const matLinen = new X({ color: "#f8f5ee", roughness: 0.88, metalness: 0.02 });
  const passePartoutMesh = new I(new Z(width + 0.14, height + 0.14, 0.06), matLinen);
  g.add(passePartoutMesh);

  // LỚP 4: Nẹp chỉ góc trong mạ vàng lá sắc sảo
  const innerGoldMat = new X({ color: "#e6ca65", roughness: 0.25, metalness: 0.85 });
  const innerGoldMesh = new I(new Z(width + 0.04, height + 0.04, 0.075), innerGoldMat);
  g.add(innerGoldMesh);

  // LỚP 5: Vải canvas / tranh nghệ thuật độ phân giải cao (PBR WebGL2 Rebound)
  const canvas = document.createElement("canvas");
  canvas.width = 2048; canvas.height = 1365;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.fillStyle = "#1e293b";
    ctx.fillRect(0, 0, 2048, 1365);
    ctx.fillStyle = "#94a3b8";
    ctx.font = 'bold 42px "Be Vietnam Pro", sans-serif';
    ctx.textAlign = "center";
    ctx.fillText(title || "Ảnh tư liệu lịch sử", 1024, 680);
  }
  let tex = new Pe(canvas);
  tex.generateMipmaps = true;

  // Tra cứu ảnh nhúng Base64 vĩnh viễn
  let resolvedUrl = imageUrl;
  if (typeof window !== "undefined" && typeof window.resolveImgUrl === "function") {
    resolvedUrl = window.resolveImgUrl(imageUrl);
  }
  if (!resolvedUrl || !resolvedUrl.startsWith('data:')) {
    if (typeof window !== "undefined" && window.__EMBEDDED_MUSEUM_IMAGES__) {
      const store = window.__EMBEDDED_MUSEUM_IMAGES__;
      resolvedUrl = store[imageUrl] || store['./' + imageUrl] || store[imageUrl.replace(/^\.\//, '')] ||
                    store['public/' + imageUrl.replace(/^(\.\/)?(public\/)?/, '')] ||
                    store['./public/' + imageUrl.replace(/^(\.\/)?(public\/)?/, '')] || resolvedUrl;
    }
  }

  // Tấm canvas dùng PBR MeshStandardMaterial với ánh sáng phản xạ tinh tế
  const artMat = new X({ map: tex, roughness: 0.35, metalness: 0.02, emissive: "#ffffff", emissiveIntensity: 0.06 });
  const artMesh = new I(new Yt(width, height), artMat);

  const applyLoadedImage = (imgSrc) => {
    try {
      const nw = imgSrc.naturalWidth || imgSrc.width || 2048;
      const nh = imgSrc.naturalHeight || imgSrc.height || 1365;
      const imgAspect = nw / nh;
      canvas.width = 2048;
      canvas.height = Math.round(2048 / imgAspect);
      const acv = document.createElement("canvas");
      acv.width = 2048;
      acv.height = Math.round(2048 / imgAspect);
      const actx = acv.getContext("2d");
      if (actx) {
        actx.drawImage(imgSrc, 0, 0, nw, nh, 0, 0, acv.width, acv.height);
      }
      const dctx = canvas.getContext("2d");
      if (dctx) {
        dctx.drawImage(imgSrc, 0, 0, nw, nh, 0, 0, canvas.width, canvas.height);
      }
      const freshTex = new Pe(acv);
      freshTex.generateMipmaps = true;
      freshTex.needsUpdate = true;
      artMat.map = freshTex;
      artMat.needsUpdate = true;
    } catch (e) {
      console.warn("Lỗi dựng tranh WebGL:", e);
    }
  };

  const img = new Image();
  if (!resolvedUrl.startsWith('data:')) {
    img.crossOrigin = "anonymous";
  }
  img.onload = () => {
    applyLoadedImage(img);
  };
  img.onerror = () => {
    if (typeof window !== "undefined") {
      let b64 = null;
      if (typeof window.resolveImgUrl === "function") {
        b64 = window.resolveImgUrl(imageUrl);
      }
      if (!b64 || !b64.startsWith('data:')) {
        const store = window.__EMBEDDED_MUSEUM_IMAGES__;
        if (store) {
          b64 = store[imageUrl] || store['./' + imageUrl] || store[imageUrl.replace(/^\.\//, '')];
        }
      }
      if (b64 && b64.startsWith('data:')) {
        img.crossOrigin = null;
        img.removeAttribute && img.removeAttribute("crossorigin");
        img.src = b64;
      }
    }
  };
  img.src = resolvedUrl;
  if (img.complete && img.naturalWidth > 0) {
    applyLoadedImage(img);
  }
  if (img.complete && (img.naturalWidth > 0 || img.width > 0)) {
    applyLoadedImage(img);
  }
  artMesh.position.z = 0.055;
  g.add(artMesh);

  // =========================================================================
  // BẢNG TÊN & CHÚ THÍCH ĐỘ PHÂN GIẢI CAO 2048 X 512 (R4 REQUIREMENT)
  // Tên tranh: 38-42px bold radiant gold, tự động xuống dòng không cắt chữ
  // Niên đại: Badge pill 30px vàng champagne nền đỏ thẫm #8c1d18
  // Chú thích: 24px trắng sáng nét căng, căn chỉnh nhiều dòng ngay ngắn
  // =========================================================================
  const plaqueCv = document.createElement("canvas");
  plaqueCv.width = 2048; plaqueCv.height = 512;
  const pctx = plaqueCv.getContext("2d");
  if (pctx) {
    // Nền kim loại đồng cổ sang trọng
    const grad = pctx.createLinearGradient(0, 0, 2048, 512);
    grad.addColorStop(0, "#1c1208");
    grad.addColorStop(0.5, "#382312");
    grad.addColorStop(1, "#1c1208");
    pctx.fillStyle = grad;
    pctx.fillRect(0, 0, 2048, 512);

    // Đường viền kép mạ vàng
    pctx.strokeStyle = "#d4af37";
    pctx.lineWidth = 10;
    pctx.strokeRect(16, 16, 2016, 480);
    pctx.strokeStyle = "#fef08a";
    pctx.lineWidth = 3;
    pctx.strokeRect(32, 32, 1984, 448);

    // Pill badge niên đại ở góc trên
    if (year) {
      pctx.fillStyle = "#8c1d18";
      pctx.fillRect(824, 46, 400, 56);
      pctx.strokeStyle = "#d4af37";
      pctx.lineWidth = 3;
      pctx.strokeRect(824, 46, 400, 56);
      pctx.fillStyle = "#fef08a";
      pctx.font = 'bold 30px "Cinzel", Georgia, serif';
      pctx.textAlign = "center";
      pctx.fillText("★ " + year + " ★", 1024, 86);
    }

    // Helper ngắt dòng chữ
    function wrapText(context, text, maxWidth) {
      const words = (text || "").split(" ");
      const lines = [];
      let cur = "";
      for (let i = 0; i < words.length; i++) {
        const test = cur ? cur + " " + words[i] : words[i];
        if (context.measureText(test).width <= maxWidth) {
          cur = test;
        } else {
          if (cur) lines.push(cur);
          cur = words[i];
        }
      }
      if (cur) lines.push(cur);
      return lines;
    }

    // Tiêu đề tranh (38px - 42px bold, vàng rực rỡ, không cắt cụt)
    pctx.fillStyle = "#fef08a";
    pctx.font = 'bold 38px "Cinzel", "Playfair Display", Georgia, serif';
    pctx.textAlign = "center";
    pctx.shadowColor = "rgba(0, 0, 0, 0.9)";
    pctx.shadowBlur = 8;
    pctx.shadowOffsetX = 2;
    pctx.shadowOffsetY = 3;

    const titleLines = wrapText(pctx, title, 1850);
    let titleY = year ? 150 : 120;
    for (let li = 0; li < Math.min(2, titleLines.length); li++) {
      pctx.fillText(titleLines[li], 1024, titleY);
      titleY += 50;
    }

    // Đường gạch chỉ vàng thanh lịch
    pctx.shadowBlur = 0;
    pctx.strokeStyle = "rgba(212, 175, 55, 0.5)";
    pctx.lineWidth = 2;
    pctx.beginPath();
    pctx.moveTo(300, titleY - 10);
    pctx.lineTo(1748, titleY - 10);
    pctx.stroke();

    // Nội dung chú thích lịch sử (24px, màu trắng ngà sáng rõ)
    pctx.fillStyle = "#f1f5f9";
    pctx.font = 'bold 24px "Be Vietnam Pro", sans-serif';
    pctx.textAlign = "center";
    const descLines = wrapText(pctx, description, 1850);
    let descY = titleY + 36;
    for (let di = 0; di < Math.min(3, descLines.length); di++) {
      pctx.fillText(descLines[di], 1024, descY);
      descY += 38;
    }
  }
  const plaqueTex = new Pe(plaqueCv);
  plaqueTex.generateMipmaps = true;

  // Bảng tên 3D kích thước rộng rãi, đặt ngay dưới chân khung tranh
  const plaqueWidth = Math.min(3.2, Math.max(2.4, width * 0.88));
  const plaqueHeight = 0.52;
  const plaqueMesh = new I(new Yt(plaqueWidth, plaqueHeight), new X({ map: plaqueTex, roughness: 0.35, metalness: 0.45, side: Xe }));
  plaqueMesh.position.set(0, -height / 2 - 0.38, 0.055);
  g.add(plaqueMesh);

  // Đèn rọi Spotlight ấm áp chuyên dụng cho bảo tàng
  const spot = new sa("#fffbeb", 2.4, 9.0, Math.PI / 4, 0.4);
  spot.position.set(0, height / 2 + 1.2, 2.4);
  spot.target = artMesh;
  g.add(spot);
  g.add(spot.target);

  if (onRegisterInteractive) {
    onRegisterInteractive(artMesh, "🖼️ " + title + " (" + year + ")", {
      title, year, imageUrl, description, shortDescription: description, hasPhoto: true
    });
    onRegisterInteractive(plaqueMesh, "🖼️ " + title + " (" + year + ")", {
      title, year, imageUrl, description, shortDescription: description, hasPhoto: true
    });
  }

  return { group: g, artMesh, plaqueMesh, spotLight: spot };
}

// -------------------------------------------------------------------------
// STANDEE MÃ QR & THUYẾT MINH BẠN THẢO 3D TẠI SẢNH ĐÓN KHÁCH (R1.1)
// -------------------------------------------------------------------------
function createEntranceQrStandee({ x = 2.4, y = 0, z = 18.2, rotY = -Math.PI / 6, onRegisterInteractive = null }) {
  const g = new It();
  g.position.set(x, y, z);
  g.rotation.y = rotY;

  // Bệ đỡ đồng cổ
  const baseMesh = new I(new Z(0.95, 0.12, 0.75), new X({ color: "#22150c", roughness: 0.4, metalness: 0.35 }));
  baseMesh.position.y = 0.06;
  baseMesh.castShadow = true;
  g.add(baseMesh);

  // Cột trụ mạ vàng champagne
  const poleMesh = new I(new Z(0.16, 1.25, 0.12), new X({ color: "#d4af37", roughness: 0.25, metalness: 0.85 }));
  poleMesh.position.y = 0.68;
  poleMesh.castShadow = true;
  g.add(poleMesh);

  // Bảng hiển thị nghiêng 15 độ
  const boardGroup = new It();
  boardGroup.position.set(0, 1.35, 0);
  boardGroup.rotation.x = -0.26; // nghiêng ~15 độ ra sau

  const boardBack = new I(new Z(1.15, 1.55, 0.06), new X({ color: "#1e2430", roughness: 0.5, metalness: 0.3 }));
  boardGroup.add(boardBack);

  const goldFrame = new I(new Z(1.20, 1.60, 0.04), new X({ color: "#d4af37", roughness: 0.2, metalness: 0.9 }));
  goldFrame.position.z = -0.01;
  boardGroup.add(goldFrame);

  // Canvas mặt bảng Standee
  const cv = document.createElement("canvas");
  cv.width = 1024; cv.height = 1400;
  const ctx = cv.getContext("2d");
  if (ctx) {
    const grad = ctx.createLinearGradient(0, 0, 1024, 1400);
    grad.addColorStop(0, "#0b1220");
    grad.addColorStop(0.5, "#182234");
    grad.addColorStop(1, "#0b1220");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 1024, 1400);

    ctx.strokeStyle = "#d4af37";
    ctx.lineWidth = 14;
    ctx.strokeRect(20, 20, 984, 1360);
    ctx.strokeStyle = "#fef08a";
    ctx.lineWidth = 3;
    ctx.strokeRect(36, 36, 952, 1328);

    ctx.fillStyle = "#fef08a";
    ctx.font = 'bold 44px "Cinzel", Georgia, serif';
    ctx.textAlign = "center";
    ctx.fillText("BẢO TÀNG LỊCH SỬ SỐ 3D", 512, 120);

    ctx.fillStyle = "#ffffff";
    ctx.font = 'bold 36px "Be Vietnam Pro", sans-serif';
    ctx.fillText("MÃ QR & THUYẾT MINH BẠN THẢO", 512, 185);

    ctx.fillStyle = "#38bdf8";
    ctx.font = '24px "Be Vietnam Pro", sans-serif';
    ctx.fillText("ĐỘI ẤP BẮC — DẤU ẤN MIỀN NAM 1961–1965", 512, 235);

    // Khung trắng vẽ mã QR
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(262, 300, 500, 500);
    ctx.strokeStyle = "#d4af37";
    ctx.lineWidth = 8;
    ctx.strokeRect(262, 300, 500, 500);

    // Tải ảnh QR Code vẽ lên standee
    const qrImg = new Image();
    qrImg.onload = () => {
      ctx.drawImage(qrImg, 282, 320, 460, 460);
      tex.needsUpdate = true;
    };
    qrImg.src = "./MA_QR_KET_NOI_BAO_TANG.png";

    ctx.fillStyle = "#fbbf24";
    ctx.font = 'bold 30px "Be Vietnam Pro", sans-serif';
    ctx.fillText("📱 QUÉT MÃ ĐỂ NGHE THUYẾT MINH", 512, 880);

    ctx.fillStyle = "#94a3b8";
    ctx.font = '22px "Be Vietnam Pro", sans-serif';
    ctx.fillText("Sử dụng camera điện thoại để quét mã QR", 512, 930);
    ctx.fillText("hoặc nhấp chuột vào bục này để nghe trực tiếp!", 512, 970);

    ctx.fillStyle = "#8c1d18";
    ctx.fillRect(150, 1030, 724, 110);
    ctx.strokeStyle = "#fef08a";
    ctx.lineWidth = 3;
    ctx.strokeRect(150, 1030, 724, 110);

    ctx.fillStyle = "#fde047";
    ctx.font = 'bold 34px "Be Vietnam Pro", sans-serif';
    ctx.fillText("🎙️ BẤM VÀO ĐÂY ĐỂ MỞ BÀI THUYẾT MINH", 512, 1095);
  }

  const tex = new Pe(cv);
  tex.generateMipmaps = true;
  const faceMesh = new I(new Yt(1.10, 1.50), new X({ map: tex, roughness: 0.35, metalness: 0.25 }));
  faceMesh.position.z = 0.035;
  boardGroup.add(faceMesh);
  g.add(boardGroup);

  if (onRegisterInteractive) {
    onRegisterInteractive(faceMesh, "🎙️ Mở Thuyết Minh Bạn Thảo & Quét Mã QR", "qr-kiosk");
  }

  return { group: g, faceMesh };
}

// HÀM TẠO MỐC TRÒN ĐÁNH SỐ TRÊN SÀN (ẢNH 1: 5, 6, 9)
function createFloorStopMarker(numberText, yearText) {
  const canvas = document.createElement("canvas");
  canvas.width = 256; canvas.height = 256;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.clearRect(0, 0, 256, 256);
    ctx.beginPath();
    ctx.arc(128, 128, 116, 0, Math.PI * 2);
    ctx.fillStyle = "rgba(15, 23, 42, 0.88)";
    ctx.fill();
    ctx.strokeStyle = "#d4af37";
    ctx.lineWidth = 8;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(128, 128, 96, 0, Math.PI * 2);
    ctx.strokeStyle = "rgba(253, 224, 71, 0.5)";
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.fillStyle = "#fef08a";
    ctx.font = '900 68px "Cinzel", Georgia, serif';
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(numberText, 128, 115);

    if (yearText) {
      ctx.fillStyle = "#38bdf8";
      ctx.font = '700 24px "Be Vietnam Pro", sans-serif';
      ctx.fillText(yearText, 128, 178);
    }
  }
  const tex = new Pe(canvas);
  const mesh = new I(new Yt(1.1, 1.1), new Se({ map: tex, transparent: true, opacity: 0.95, side: Xe }));
  mesh.rotation.x = -Math.PI / 2;
  return mesh;
}

// HÀM TẠO TUYẾN MŨI TÊN DẪN ĐƯỜNG CHEVRON TRÊN SÀN (ẢNH 2)
function createChevronPath(points) {
  const group = new It();
  const cv = document.createElement("canvas");
  cv.width = 128; cv.height = 64;
  const cx = cv.getContext("2d");
  if (cx) {
    cx.clearRect(0, 0, 128, 64);
    [24, 64, 104].forEach(xCenter => {
      cx.beginPath();
      cx.moveTo(xCenter - 18, 10);
      cx.lineTo(xCenter + 8, 32);
      cx.lineTo(xCenter - 18, 54);
      cx.strokeStyle = "#d4af37";
      cx.lineWidth = 9;
      cx.lineCap = "round";
      cx.lineJoin = "round";
      cx.stroke();
    });
  }
  const tex = new Pe(cv);

  for (let i = 0; i < points.length - 1; i++) {
    const p1 = points[i];
    const p2 = points[i + 1];
    const dx = p2[0] - p1[0];
    const dz = p2[1] - p1[1];
    const dist = Math.hypot(dx, dz);
    if (dist < 0.6) continue;
    const angle = Math.atan2(dx, dz);
    const count = Math.max(1, Math.floor(dist / 1.4));
    for (let c = 1; c <= count; c++) {
      const t = c / (count + 1);
      const ax = p1[0] + dx * t;
      const az = p1[1] + dz * t;
      const arrow = new I(new Yt(0.65, 0.32), new Se({ map: tex, transparent: true, opacity: 0.85, side: Xe }));
      arrow.rotation.x = -Math.PI / 2;
      arrow.rotation.z = -angle + Math.PI / 2;
      arrow.position.set(ax, 0.024, az);
      group.add(arrow);
    }
  }
  return group;
}

// HÀM TẠO GHẾ BĂNG BẢO TÀNG (ẢNH 1)
function createMuseumWoodBench(x, y, z, rotY = 0) {
  const bench = new It();
  bench.position.set(x, y, z);
  bench.rotation.y = rotY;

  const benchWoodMat = new X({ color: "#3e2723", roughness: 0.5, metalness: 0.1 });
  const benchMetalMat = new X({ color: "#1e293b", roughness: 0.3, metalness: 0.8 });

  const seat = new I(new Z(2.6, 0.08, 0.70), benchWoodMat);
  seat.position.y = 0.45;
  seat.castShadow = true; seat.receiveShadow = true;
  bench.add(seat);

  [-1.1, 1.1].forEach(sx => {
    [-0.24, 0.24].forEach(sz => {
      const leg = new I(new Z(0.06, 0.45, 0.06), benchMetalMat);
      leg.position.set(sx, 0.225, sz);
      bench.add(leg);
    });
    const cross = new I(new Z(0.04, 0.04, 0.52), benchMetalMat);
    cross.position.set(sx, 0.15, 0);
    bench.add(cross);
  });
  return bench;
}

