const { tank: tankModel, turretGroup: tankTurret } = createKhu3Tank843Model();
tankModel.position.set(-11.5, 0.63, -18.0);
tankModel.scale.set(1.4, 1.4, 1.4);
tankModel.rotation.y = 0.44; // Xoay chéo ~25.2 độ hướng về đại lộ trung tâm
