// Đèn Spotlight âm trần rọi ấm áp riêng cho Xe Tăng 843 (góc 45 độ tôn hình khối)
const tankSpot = new sa("#fffbeb", 2.6, 12.0, Math.PI / 4.2, 0.45);
tankSpot.position.set(-11.5, ie - 0.3, -16.0);
tankSpot.target = tankModel;
