$.add(tankSpot.target);

// --- 5. BỐ TRÍ TRỰC THĂNG UH-1 Ở PHÍA ĐÔNG ĐẠI LỘ (X = +11.5, Z = -18.0) XOAY CHÉO ~-25.2 ĐỘ ---
const heliPedestal = createKhu3ModelPedestal({
  x: 11.5, y: 0.0, z: -18.0, width: 4.5, depth: 12.0, height: 0.45,
  title: "CHIẾN LỢI PHẨM LỊCH SỬ: TRỰC THĂNG BELL UH-1 IROQUOIS",
  subtitle: "KHÍ TÀI 'TRỰC THĂNG VẬN' BỊ ĐÁNH BẠI TRONG CHIẾN TRANH ĐẶC BIỆT",
  plaqueText: "🏛️ BẤM VÀO TRỰC THĂNG ĐỂ BẬT/TẮT QUAY CÁNH QUẠT & XEM TƯ LIỆU"
});
$.add(heliPedestal.group);

const { heli: heliModel, rotorGroup: heliMainRotor, tailRotorGroup: heliTailRotor } = createKhu3HelicopterUH1Model();
heliModel.position.set(11.5, 0.45, -18.0);
heliModel.rotation.y = -0.44; // Xoay chéo ~-25.2 độ hướng về đại lộ trung tâm
$.add(heliModel);

// Đèn Spotlight âm trần rọi ấm áp riêng cho Trực Thăng UH-1 (góc 45 độ tôn hình khối)
const heliSpot = new sa("#fffbeb", 2.6, 12.0, Math.PI / 4.2, 0.45);
heliSpot.position.set(11.5, ie - 0.3, -16.0);
heliSpot.target = heliModel;
